import{_ as s,o as e,c as i,a6 as n}from"./chunks/framework.DL_pga9_.js";const g=JSON.parse('{"title":"Modules and Imports","description":"","frontmatter":{},"headers":[],"relativePath":"guide/modules-and-imports.md","filePath":"guide/modules-and-imports.md","lastUpdated":1781686130000}'),t={name:"guide/modules-and-imports.md"};function l(p,a,o,r,d,h){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="modules-and-imports" tabindex="-1">Modules and Imports <a class="header-anchor" href="#modules-and-imports" aria-label="Permalink to “Modules and Imports”">​</a></h1><p>NG uses a file-based module system. Every <code>.ng</code> file is a module, and you control visibility with <code>export</code> and <code>import</code>.</p><h2 id="module-basics" tabindex="-1">Module Basics <a class="header-anchor" href="#module-basics" aria-label="Permalink to “Module Basics”">​</a></h2><h3 id="every-file-is-a-module" tabindex="-1">Every File is a Module <a class="header-anchor" href="#every-file-is-a-module" aria-label="Permalink to “Every File is a Module”">​</a></h3><p>When you create <code>math.ng</code>:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// math.ng — this is a module</span></span>
<span class="line"><span>fun add(x: i32, y: i32) -&gt; i32 =&gt; x + y;</span></span></code></pre></div><p>By default, nothing is visible to other modules. You must <strong>export</strong> what you want to expose.</p><h2 id="exporting" tabindex="-1">Exporting <a class="header-anchor" href="#exporting" aria-label="Permalink to “Exporting”">​</a></h2><h3 id="the-export-keyword" tabindex="-1">The <code>export</code> Keyword <a class="header-anchor" href="#the-export-keyword" aria-label="Permalink to “The export Keyword”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// math.ng</span></span>
<span class="line"><span>export fun add(x: i32, y: i32) -&gt; i32 =&gt; x + y;</span></span>
<span class="line"><span>export fun multiply(x: i32, y: i32) -&gt; i32 =&gt; x * y;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// This is private — not visible outside this file</span></span>
<span class="line"><span>fun helper(x: i32) -&gt; i32 =&gt; x + 1;</span></span></code></pre></div><h3 id="wildcard-export" tabindex="-1">Wildcard Export <a class="header-anchor" href="#wildcard-export" aria-label="Permalink to “Wildcard Export”">​</a></h3><p>Use <code>exports *</code> in the module declaration to export everything:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>module math exports *;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun add(x: i32, y: i32) -&gt; i32 =&gt; x + y;</span></span>
<span class="line"><span>fun multiply(x: i32, y: i32) -&gt; i32 =&gt; x * y;</span></span></code></pre></div><p>All top-level bindings are now exported.</p><h3 id="module-declaration-syntax" tabindex="-1">Module Declaration Syntax <a class="header-anchor" href="#module-declaration-syntax" aria-label="Permalink to “Module Declaration Syntax”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>module &lt;name&gt; exports &lt;list&gt;;</span></span></code></pre></div><p>The module name is used for qualified imports.</p><h2 id="importing" tabindex="-1">Importing <a class="header-anchor" href="#importing" aria-label="Permalink to “Importing”">​</a></h2><h3 id="wildcard-import" tabindex="-1">Wildcard Import <a class="header-anchor" href="#wildcard-import" aria-label="Permalink to “Wildcard Import”">​</a></h3><p>Import all exported symbols into the current namespace:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// main.ng</span></span>
<span class="line"><span>import math (*);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>add(1, 2);          // OK</span></span>
<span class="line"><span>multiply(3, 4);     // OK</span></span></code></pre></div><h3 id="named-import" tabindex="-1">Named Import <a class="header-anchor" href="#named-import" aria-label="Permalink to “Named Import”">​</a></h3><p>Import specific symbols:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import math (add);   // only add is imported</span></span>
<span class="line"><span>add(1, 2);           // OK</span></span>
<span class="line"><span>// multiply(3, 4);</span><span>   // ERROR: not imported</span></span></code></pre></div><h3 id="qualified-import" tabindex="-1">Qualified Import <a class="header-anchor" href="#qualified-import" aria-label="Permalink to “Qualified Import”">​</a></h3><p>Use a module prefix to avoid name conflicts:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import math;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val result = math::add(1, 2);</span></span></code></pre></div><h3 id="mixed-import" tabindex="-1">Mixed Import <a class="header-anchor" href="#mixed-import" aria-label="Permalink to “Mixed Import”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import math (add);           // unqualified add</span></span>
<span class="line"><span>import math;                 // also provides math:: prefix</span></span></code></pre></div><h3 id="renaming-imports" tabindex="-1">Renaming Imports <a class="header-anchor" href="#renaming-imports" aria-label="Permalink to “Renaming Imports”">​</a></h3><p>You can alias imports to avoid name clashes:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.prelude (print as show);</span></span>
<span class="line"><span>show(&quot;Hello!&quot;);   // prints &quot;Hello!&quot;</span></span></code></pre></div><h2 id="module-resolution" tabindex="-1">Module Resolution <a class="header-anchor" href="#module-resolution" aria-label="Permalink to “Module Resolution”">​</a></h2><h3 id="search-paths" tabindex="-1">Search Paths <a class="header-anchor" href="#search-paths" aria-label="Permalink to “Search Paths”">​</a></h3><p>When you <code>import math</code>, NG searches for <code>math.ng</code> in:</p><ol><li>The directory of the importing file</li><li>The <code>lib/</code> directory (standard library)</li><li>The <code>../lib/</code> directory (relative to binary)</li></ol><h3 id="module-paths-with-dots" tabindex="-1">Module Paths with Dots <a class="header-anchor" href="#module-paths-with-dots" aria-label="Permalink to “Module Paths with Dots”">​</a></h3><p>Dots in module names map to directory paths:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.prelude;   // loads lib/std/prelude.ng</span></span>
<span class="line"><span>import std.string;    // loads lib/std/string.ng</span></span>
<span class="line"><span>import std.io;        // loads lib/std/io.ng</span></span></code></pre></div><h2 id="circular-imports" tabindex="-1">Circular Imports <a class="header-anchor" href="#circular-imports" aria-label="Permalink to “Circular Imports”">​</a></h2><p>Circular imports are <strong>not supported</strong>. If module A imports module B, module B cannot import module A (directly or transitively).</p><h2 id="standard-library-import" tabindex="-1">Standard Library Import <a class="header-anchor" href="#standard-library-import" aria-label="Permalink to “Standard Library Import”">​</a></h2><p>The <code>std.prelude</code> module is implicitly imported into every NG file. Other standard library modules must be explicitly imported:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import std.io;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val content = readFile(&quot;data.txt&quot;);</span></span>
<span class="line"><span>import std.string;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val lines = split(content, &quot;\\n&quot;);</span></span></code></pre></div><h2 id="bytecode-module-artifacts-ngo" tabindex="-1">Bytecode Module Artifacts (<code>.ngo</code>) <a class="header-anchor" href="#bytecode-module-artifacts-ngo" aria-label="Permalink to “Bytecode Module Artifacts (.ngo)”">​</a></h2><p>NG can compile modules to bytecode for faster loading:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Compile to bytecode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/ngi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-ngo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> math.ngo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example/math.ng</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run referencing the .ngo artifact</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build/ngi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example/main.ng</span></span></code></pre></div><p>The module loader automatically:</p><ol><li>Checks for a <code>.ngo</code> file alongside the source</li><li>Verifies the source hash matches (detects staleness)</li><li>Falls back to source compilation if the artifact is stale or incompatible</li></ol><h2 id="exporting-types" tabindex="-1">Exporting Types <a class="header-anchor" href="#exporting-types" aria-label="Permalink to “Exporting Types”">​</a></h2><p>Types, functions, and even trait implementations can be exported:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// shapes.ng</span></span>
<span class="line"><span>module shapes exports *;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>type Point {</span></span>
<span class="line"><span>    x: i32;</span></span>
<span class="line"><span>    y: i32;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export fun origin() -&gt; Point {</span></span>
<span class="line"><span>    return new Point { x: 0, y: 0 };</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Importing export impls</span></span>
<span class="line"><span>module math exports *;</span></span>
<span class="line"><span>impl Show for i32 { ... }</span></span></code></pre></div><p>When you import <code>shapes</code>, you get access to the <code>Point</code> type and the <code>origin</code> function.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><p>Continue to <a href="./generics">Generics</a> to learn about writing reusable, type-parameterized code.</p><blockquote><p><strong>Try it:</strong> <code>example/08.imports.ng</code> — Basic imports <strong>Try it:</strong> <code>example/13.import_std_prelude.ng</code> — Importing standard library <strong>Try it:</strong> <code>example/56.stdlib_modules.ng</code> — Multiple module interactions</p></blockquote>`,56)])])}const m=s(t,[["render",l]]);export{g as __pageData,m as default};
